```rust
use std::sync::atomic::{AtomicI32, Ordering};
use std::sync::Arc;
use std::thread;

static C: AtomicI32 = AtomicI32::new(0);

fn w1() {
    loop {
        let exp = C.load(Ordering::SeqCst);
        let obs = C.compare_exchange(exp, exp + 1, Ordering::SeqCst, Ordering::SeqCst);
        match obs {
            Ok(_) => break,
            Err(_) => continue,
        }
    }
}

fn w2() {
    loop {
        let exp = C.load(Ordering::SeqCst);
        let obs = C.compare_exchange(exp, exp + 1, Ordering::SeqCst, Ordering::SeqCst);
        match obs {
            Ok(_) => break,
            Err(_) => continue,
        }
    }
}

fn main() {
    let h1 = thread::spawn(move || w1());
    let h2 = thread::spawn(move || w2());
    h1.join().unwrap();
    h2.join().unwrap();
    let done = C.load(Ordering::SeqCst);
    println!("DONE done={}", done / 2);
}
