    // w2 performs its work while holding the permit
    permit.release();
}

fn main() {
    let s: Arc<Semaphore> = Semaphore::new(1);

    let s1 = Arc::clone(&s);
    let t1 = thread::spawn(move || {
        w1(&s1);
