use std::sync::Arc;
use std::thread;

use concir_sync::Semaphore;

fn w1(s: &Arc<Semaphore>) {
    let _permit = s.acquire();
    // critical section: worker performs its work while holding one permit
    drop(_permit);
}

fn w2(s: &Arc<Semaphore>) {
    let _permit = s.acquire();
    // critical section: worker performs its work while holding one permit
    drop(_permit);
}

fn w3(s: &Arc<Semaphore>) {
    let _permit = s.acquire();
    // critical section: worker performs its work while holding one permit
    drop(_permit);
}

